"""Build local composition study with an inspectable fixture path."""
from pathlib import Path
import json,re
P=Path(__file__).resolve().parent
s=(P/'research.html').read_text()
hero='''<section class="hero"><div class="hero-copy"><p class="kicker">RX / INSPECTABLE AGENT BOUNDARIES</p><h1>Every claim.<br>A visible <em>path.</em></h1><p class="intro">A draft is only as defensible as the evidence behind it. See what the agent can use—and where its authority ends.</p><a class="cta" href="#copy">READ THE POST <span>↗</span></a><p class="quiet">GLP-1 prior authorization · Synthetic demonstration</p></div><div class="path-panel"><div class="panel-label"><span>01 / DECLARED POLICY PATH</span><span class="live-dot">INSPECTABLE</span></div><div class="path-choice" role="group" aria-label="Choose a policy path"><button class="selected" data-path="scope" aria-pressed="true">Scope + BMI</button><button data-path="dose" aria-pressed="false">Starting dose</button><button data-path="renal" aria-pressed="false">Renal documentation</button></div><div class="path-canvas"><div class="node root"><span>INPUT</span><strong>Wegovy start request</strong></div><div class="connector"><span id="edge-one">PA-E01 · requires</span></div><div class="node"><span>DECLARED CRITERION</span><strong id="criterion-one">Adult weight-management scope</strong></div><div id="second-path"><div class="connector"><span>PA-E02 · requires</span></div><div class="node"><span>DEPENDENT CRITERION</span><strong>BMI with comorbidity branch</strong></div></div></div><div class="evidence"><span class="evidence-label">EDGE RECORD / <b id="record-id">PA-E01</b></span><p id="rationale"></p><a id="source-link" target="_blank" rel="noopener">Inspect source ↗</a></div><p class="path-note">Illustrates fixture relationships. No patient eligibility is inferred here.</p></div></section>
<section class="boundary-strip"><span>THE AUTHORITY BOUNDARY</span><p>Walk the rules <i>→</i> Constrain the draft <i>→</i> Human review</p><strong>SUBMIT BLOCKED ⊘</strong></section>'''
s=re.sub(r'<section class="hero">.*?</section>',hero,s,count=1,flags=re.S)
s=s.replace('href="research.css"','href="research.css"><link rel="stylesheet" href="research-v2.css"')
s=s.replace('<title>Trace the rule · Local post study</title>','<title>Every claim. A visible path. · Local design study</title>')
edges=json.loads((P.parent.parent/'data/synthetic-policy.json').read_text())['edges']
data={e['id']:e for e in edges}
js='''<script>const fixture=DATA;const paths={scope:['PA-E01','Adult weight-management scope'],dose:['PA-E03','Starting dose: 0.25 mg weekly'],renal:['PA-E08','eGFR documented; no cutoff encoded']};function showPath(key){const [id,label]=paths[key];document.getElementById('edge-one').textContent=id+' · requires';document.getElementById('criterion-one').textContent=label;document.getElementById('second-path').hidden=key!=='scope';document.getElementById('record-id').textContent=id;document.getElementById('rationale').textContent=fixture[id].rationale;document.getElementById('source-link').href=fixture[id].source;document.querySelectorAll('[data-path]').forEach(b=>{b.classList.toggle('selected',b.dataset.path===key);b.setAttribute('aria-pressed',b.dataset.path===key)})}document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>showPath(b.dataset.path));showPath('scope');</script>'''.replace('DATA',json.dumps(data))
s=s.replace('</body>',js+'</body>')
from native_graph import diagram
native = diagram(edges)
s=re.sub(r'<img src="research-graph.svg".*?>',native,s,count=1,flags=re.S)
s=s.replace('</head>','<link rel="stylesheet" href="native-graph.css"></head>')
s=s.replace('</body>','<script src="native-graph.js"></script></body>')
s=s.replace('href="research-graph.png"','href="native-graph.png"').replace('EDITABLE SVG ↗','ORIGINAL SVG ARTWORK ↗')
(P/'native-graph-export.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Live graph export</title><link rel="stylesheet" href="research.css"><link rel="stylesheet" href="native-graph.css"><style>body{margin:0}.native-graph{border:0}</style></head><body>'+native+'<script src="native-graph.js"></script></body></html>')
(P/'research-v2.html').write_text(s)
p=P/'comparison.html'
